)

// Location identifies a position in the original YAML file.
type Location struct {
	File   string "'`json:"file,omitempty"`
	Line   int    `json:"line"`
	Column int    `json:"column"`
}

// Error describes one validation failure.
type Error struct {
	Path     string   `json:"path"`
	Message  string   `json:"message"`
	Location Location `json:"location"`
}

// Result contains every error found while validating a YAML document.
type Result struct {
	Errors []Error `json:"errors"`
}

// FeaturesValidator holds the compiled feature schema.
type FeaturesValidator struct {
	cue *cue.Context
	v   cue.Value
}

// NewFeaturesValidator compiles the embedded feature schema.
func NewFeaturesValidator() (*FeaturesValidator, error) {
	cctx := cuecontext.New()
	v := cctx.CompileBytes(cueFile)
	if err := v.Err(); err != nil {
		return nil, fmt.Errorf("compile feature schema: %w", err)
	}
	return &FeaturesValidator{cue: cctx, v: v}, nil
}

// Validate checks YAML content and returns all validation failures.
func (fv *FeaturesValidator) Validate(file string, b []byte) (Result, error) {
	result := Result{Errors: []Error{}}
	f, err := yaml.Extract(file, b)
	if err == nil {
		value := fv.v.Unify(fv.cue.BuildFile(f, cue.Scope(fv.v)))
		err = value.Validate()
	}
	if err == nil {
		return result, nil
	}

	for _, e := range cueerror.Errors(err) {
		format, args := e.Msg()
		message := fmt.Sprintf(format, args...)
		if message == "" {
			message = e.Error()
		}
		result.Errors = append(result.Errors, Error{
			Path:     strings.Join(e.Path(), "."),
			Message:  message,
			Location: errorLocation(file, e),
		})
	}
	if len(result.Errors) == 0 {
		result.Errors = append(result.Errors, Error{Message: err.Error(), Location: Location{File: file}})
	}
	return result, ErrValidationFailed
}

// errorLocation prefers a source position in the YAML file. CUE also includes
// schema positions in InputPositions, often before the offending YAML field.
func errorLocation(file string, e cueerror.Error) Location {
